<script lang="ts">import DataTable from "$lib/components/DataTable.svelte"; interface Props { data: { logs: { data: { items: Array<{ id: string; actor: string | null; description: string; log_name: string | null; event: string | null; subject_id: string | null; created_at: string | null }> } } }; } let { data }: Props = $props(); function date(value: string | null): string { return value ? new Intl.DateTimeFormat(undefined, { dateStyle: "medium", timeStyle: "short" }).format(new Date(value)) : "—"; }</script>
<svelte:head><title>Activity logs | WebGuard</title></svelte:head><main class="mx-auto w-[min(78rem,calc(100%_-_2rem))] py-6 sm:py-12"><header class="mb-8"><p class="m-0 text-[0.8125rem] font-extrabold tracking-[0.1em] text-wg-accent uppercase">Administration</p><h1 class="mt-2 text-[clamp(2rem,6vw,3rem)] leading-[1.1] font-bold">Activity logs</h1><p class="mt-3 leading-6 text-wg-text-muted">Review privileged and operational events for auditability.</p></header>{#if data.logs.data.items.length === 0}<p class="rounded-2xl border border-wg-border bg-wg-surface p-6 text-wg-text-muted">No activity has been recorded.</p>{:else}<DataTable caption="Activity logs"><thead><tr><th>Actor</th><th>Description</th><th>Event</th><th>Subject</th><th>Time</th></tr></thead><tbody>{#each data.logs.data.items as log (log.id)}<tr><td>{log.actor ?? "System"}</td><td>{log.description}</td><td>{log.event ?? log.log_name ?? "—"}</td><td>{log.subject_id ?? "—"}</td><td>{date(log.created_at)}</td></tr>{/each}</tbody></DataTable>{/if}</main>
